-- BIRD database 'codebase_comments' translated to PostgreSQL.
-- Generated by research/advtext2sql/delivery/build.py from the live
-- benchmark server; types, keys and column comments are the server's own.

CREATE TABLE "method" (
    "id" bigint NOT NULL,
    "name" text,
    "fullcomment" text,
    "summary" text,
    "apicalls" text,
    "commentisxml" bigint,
    "sampledat" bigint,
    "solutionid" bigint,
    "lang" text,
    "nametokenized" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "methodparameter" (
    "id" bigint NOT NULL,
    "methodid" text,
    "type" text,
    "name" text,
    PRIMARY KEY ("id")
);

CREATE TABLE "repo" (
    "id" bigint NOT NULL,
    "url" text,
    "stars" bigint,
    "forks" bigint,
    "watchers" bigint,
    "processedtime" bigint,
    PRIMARY KEY ("id")
);

CREATE TABLE "solution" (
    "id" bigint NOT NULL,
    "repoid" bigint,
    "path" text,
    "processedtime" bigint,
    "wascompiled" bigint,
    PRIMARY KEY ("id")
);

